export const getGetGrantCatalogUrl = (params?: GetGrantCatalogParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/grants/catalog?${stringifiedParams}` : `/api/grants/catalog`
}

/**
 * Returns grant competitions whose official application status and dates have been verified. A refresh request rechecks official sources subject to the server refresh limit.
 * @summary List verified open grant competitions
 */
